import React, {useState, useEffect, useRef, useCallback, CSSProperties} from 'react'
import {createPortal} from 'react-dom'
import {colors, spacing, textStyles} from 'app/theme/foundation'
import {FontStyles}      from 'app/ui-kits/fonts'
import {ZimmLogo}        from 'app/ui-kits/atoms/ZimmLogo'
import {ZimmIcon}        from 'app/ui-kits/atoms/ZimmIcon'
import {ZimmNavItem}     from 'app/ui-kits/atoms/ZimmNavItem'
import {ZimmButton}      from 'app/ui-kits/atoms/ZimmButton'
import {ZimmTextInput}   from 'app/ui-kits/atoms/ZimmTextInput'
import {ZimmInputAction} from 'app/ui-kits/molecules/ZimmInputAction'
import type {FooterConfigEntry} from 'app/types/contentful'
import {FOOTER_FIXTURE} from './contentfulFixture'

// ---------------------------------------------------------------------------
// Local constants — values not yet in the design token foundation
// ---------------------------------------------------------------------------
// Figma space/1200 — no matching token in spacing.ts yet
const SPACE_SECTION = '48px'
// Site Map column gap @ narrow tablet 768-859px — spacing['3xl'] (40px) prevents site map overflow.
// At 768px: subscribe=320px, content=688px → links get 368px. 3 auto cols (~80px ea) + 2×40px = 320px < 368px ✓
// If spacing['5xl'] (80px) were used: 3 cols + 2×80px ≈ 400px > 368px → links-inner overflows subscribe by 32px.
// spacing['3xl'] is also used in the mobile links-inner gap — same value, distinct semantic context.
// Site Map column gap @ wide tablet 860px+ — spacing['5xl'] (80px) = alias/space/2000, Figma spec gap
// Site Map column gap @ desktop (1024px+) — no token yet; 120px not in spacing scale
const NAV_GAP_DESKTOP = '120px'
// Figma fixed nav/legal grid columns — not a spacing scale value
const FIXED_COL_WIDTH = '140px'
// Figma subscribe column fixed width — not in spacing scale
const SUBSCRIBE_COL_WIDTH = '320px'
// Figma subscribe body text max-width — not in spacing scale
const SUBSCRIBE_BODY_MAX_W = '200px'
// Figma divider: raw SVG exports as stroke="white" with no solid grey fill anywhere in the
// subtree (confirmed via get_variable_defs — no border/grey token bound here at all). Sampling
// the rendered pixel over the #191919 background gives (140,140,140), which is exactly white at
// 50% opacity composited on that bg — not a flat grey literal, so rgba() rather than a hex token.
const BORDER_DIVIDER_COLOUR = 'rgba(255, 255, 255, 0.5)'

// Named constant to avoid magic string comparison in the render tree
const CONTACT_GROUP_HEADING = 'Contact'

// CSS breakpoint thresholds — matches Chakra's built-in md (768px) and lg (1024px) breakpoints
const BP_TABLET       = 768
const BP_TABLET_WIDE  = 860   // wide-tablet threshold: min width where NAV_GAP_TABLET (80px) fits
const BP_DESKTOP      = 1024

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------
type FooterProps = {
    /** Contentful FooterConfigEntry. Pass FOOTER_FIXTURE from contentfulFixture.ts in stories/tests. */
    data?:              FooterConfigEntry
    copyrightYear?:     number
    /** Forces SubscribeSection into its post-submit state. For Storybook/tests only. */
    initialSubscribed?: boolean
    /** href for the Privacy Policy link inside the subscribe modal (HPC-037). Locale-aware at runtime. */
    privacyPolicyHref?: string
}

// ---------------------------------------------------------------------------
// Shared style objects — sourced from design token foundation, no hardcoded values

